import assert from "node:assert/strict";
import { test } from "node:test";
import { MemoryRepository } from "../src/repository.js";
import { listScheduleSlots, schedule } from "../src/scheduling.js";
const availability = (providerId, date, windows = ["09:00-19:00"]) => ({ id: `${providerId}-${date}`, providerId, cityId: "blr", zoneId: "blr-east", date, windows, source: "roster", updatedAt: "2026-08-04T00:00:00.000Z" });
const booking = (id, providerId, serviceCode, start, end, capacityUnits = 1) => ({ id, legacyIds: [], idempotencyKey: `key-${id}`, cityId: "blr", zoneId: "blr-east", customerId: "cus_10428", petIds: ["pet_bruno"], serviceCode, packageCode: "test", addonCodes: [], scheduledStart: start, scheduledEnd: end, status: "assigned", channel: "operations_assisted", totalAmount: 1000, providerId, assignmentMode: "automatic", capacityUnits, createdBy: "ops", createdAt: start, updatedAt: start });
test("grooming uses the roster and rejects overlap plus travel buffer", async () => { const r = new MemoryRepository(); await r.upsertAvailability(availability("pro_arjun", "2026-08-10")); r.bookings.push(booking("busy", "pro_arjun", "grooming", "2026-08-10T05:45:00.000Z", "2026-08-10T08:00:00.000Z")); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "grooming", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T03:30:00.000Z", scheduledEnd: "2026-08-10T05:30:00.000Z" }); assert.equal(d.provider, null); assert.match(d.evaluations[0].reasons.join(" "), /buffer/); });
test("training reserves one trainer across a recurring cadence", async () => { const r = new MemoryRepository(); for (const date of ["2026-08-10", "2026-08-17", "2026-08-24", "2026-08-31"])
    await r.upsertAvailability(availability("pro_nisha", date)); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "dog_training", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T04:30:00.000Z", scheduledEnd: "2026-08-10T05:30:00.000Z", occurrences: 4, cadenceDays: 7 }); assert.equal(d.provider?.id, "pro_nisha"); assert.equal(d.occurrences.length, 4); assert.equal(d.occurrences[3]?.start, "2026-08-31T04:30:00.000Z"); });
test("training supports multi-day weekly patterns", async () => { const r = new MemoryRepository(); for (const date of ["2026-08-10", "2026-08-13", "2026-08-17", "2026-08-20"])
    await r.upsertAvailability(availability("pro_nisha", date)); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "dog_training", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T04:30:00.000Z", scheduledEnd: "2026-08-10T05:30:00.000Z", occurrences: 4, weekdays: [1, 4] }); assert.deepEqual(d.occurrences.map(x => x.start.slice(0, 10)), ["2026-08-10", "2026-08-13", "2026-08-17", "2026-08-20"]); });
test("boarding locks capacity for the complete date range", async () => { const r = new MemoryRepository(); for (const date of ["2026-08-10", "2026-08-11", "2026-08-12"])
    await r.upsertAvailability(availability("host_ananya", date, ["00:00-23:59"])); r.bookings.push(booking("stay1", "host_ananya", "boarding", "2026-08-10T06:30:00.000Z", "2026-08-12T05:30:00.000Z", 3)); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "boarding", petIds: ["pet_bruno", "pet_bruno"], scheduledStart: "2026-08-10T06:30:00.000Z", scheduledEnd: "2026-08-12T05:30:00.000Z" }); assert.equal(d.provider, null); assert.match(d.evaluations[0].reasons.join(" "), /Capacity 4 exceeded/); });
test("pet sitting supports overnight capacity and visit scheduling", async () => { const r = new MemoryRepository(); await r.upsertAvailability(availability("sit_rohit", "2026-08-10")); await r.upsertAvailability(availability("sit_rohit", "2026-08-11")); const visit = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "pet_sitting", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T09:30:00.000Z", scheduledEnd: "2026-08-10T10:30:00.000Z", careMode: "visit" }); const overnight = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "pet_sitting", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T12:30:00.000Z", scheduledEnd: "2026-08-11T03:30:00.000Z", careMode: "overnight" }); assert.equal(visit.provider?.id, "sit_rohit"); assert.equal(overnight.provider?.id, "sit_rohit"); });
test("declined providers can be excluded and alternatives reranked", async () => { const r = new MemoryRepository(); await r.upsertAvailability(availability("pro_nisha", "2026-08-10")); await r.upsertAvailability(availability("pro_kiran", "2026-08-10")); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "dog_training", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T04:30:00.000Z", scheduledEnd: "2026-08-10T05:30:00.000Z", excludeProviderIds: ["pro_nisha"] }); assert.equal(d.provider?.id, "pro_kiran"); });
test("availability API slots come from executable schedule checks", async () => { const r = new MemoryRepository(); await r.upsertAvailability(availability("pro_arjun", "2026-08-10")); const slots = await listScheduleSlots(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "grooming", date: "2026-08-10", petIds: ["pet_bruno"] }); assert.ok(slots.some(x => x.available)); assert.ok(slots.every(x => typeof x.eligibleProviders === "number")); });
test("returns three ranked choices and applies custom business rules", async () => { const r = new MemoryRepository(); for (const id of ["pro_arjun", "pro_kiran", "pro_sanjay"])
    await r.upsertAvailability(availability(id, "2026-08-10")); const d = await schedule(r, { cityId: "blr", zoneId: "blr-east", serviceCode: "grooming", petIds: ["pet_bruno"], scheduledStart: "2026-08-10T03:30:00.000Z", scheduledEnd: "2026-08-10T05:30:00.000Z", customRules: [{ code: "east_min_rating", field: "rating", operator: "gte", value: 4.7 }] }); assert.equal(d.shortlist.length, 3); assert.equal(d.shortlist[0]?.provider.id, "pro_arjun"); assert.ok(d.evaluations.every(item => item.reasons.some(reason => /passed|Custom rule/.test(reason)))); });
